using System;using System.Linq;using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;
namespace HotelTogether.Editor {
 public static class HotelUtilitiesBuilder {
  const string Folder="Assets/HotelTogether/Models/Utilities/";static Transform root;static Material steel,blue,black;static int models,pipes;
  static Bounds BoundsOf(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
  static GameObject Model(string file,string part,Vector3 center,Vector3 size,Quaternion rotation,string label,bool solid=false,Quaternion? importFrame=null){var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+file+".glb"));GameObject model;if(part==null)model=source;else{var r=source.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.StartsWith(part));model=UnityEngine.Object.Instantiate(r.gameObject);model.transform.SetPositionAndRotation(Vector3.zero,r.transform.rotation);model.transform.localScale=r.transform.lossyScale;UnityEngine.Object.DestroyImmediate(source);}var go=new GameObject(label);go.transform.SetParent(root);var normalize=new GameObject("Imported model normalization").transform;normalize.SetParent(go.transform,false);model.transform.SetParent(normalize,true);if(importFrame.HasValue)model.transform.rotation=importFrame.Value*model.transform.rotation;var b=BoundsOf(model);normalize.localScale=new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z);b=BoundsOf(model);normalize.position-=b.center;go.transform.SetPositionAndRotation(center,rotation);if(solid){var c=go.AddComponent<BoxCollider>();c.size=size;var obstacle=go.AddComponent<NavMeshObstacle>();obstacle.shape=NavMeshObstacleShape.Box;obstacle.size=size;obstacle.carving=true;}models++;return go;}
  static GameObject Box(string label,Vector3 p,Vector3 size,Material mat,bool solid=false){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=label;go.transform.SetParent(root);go.transform.position=p;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=mat;if(!solid)UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());return go;}
  static Material Mat(string name,Color color){string dir="Assets/HotelTogether/Art/Utilities/";System.IO.Directory.CreateDirectory(dir);var m=AssetDatabase.LoadAssetAtPath<Material>(dir+name+".mat");if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=color};AssetDatabase.CreateAsset(m,dir+name+".mat");}return m;}
  static void Pipe(Vector3 a,Vector3 b,float diameter=.09f){var d=b-a;Model("low_poly_electrical_wirespipe_set","Straight_Pipe_MetalPipes",(a+b)*.5f,new Vector3(diameter,d.magnitude,diameter),Quaternion.FromToRotation(Vector3.up,d),"Water / electrical conduit");pipes++;int count=Mathf.Max(1,Mathf.CeilToInt(d.magnitude/2));for(int i=0;i<=count;i++){var p=Vector3.Lerp(a,b,(float)i/count);bool mounted=false;foreach(var direction in new[]{Vector3.left,Vector3.right,Vector3.forward,Vector3.back}){if(!Physics.Raycast(p,direction,out var hit,.4f,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore)||Mathf.Abs(hit.normal.y)>.1f||hit.collider.transform.IsChildOf(root)||hit.collider.attachedRigidbody||hit.collider.GetComponentInParent<HotelItem>())continue;var size=new Vector3(.12f,.12f,.12f);if(Mathf.Abs(direction.x)>.5f)size.x=hit.distance+.035f;else size.z=hit.distance+.035f;Box("Wall pipe bracket",(p+hit.point)*.5f,size,steel);mounted=true;break;}if(!mounted&&Mathf.Abs(d.y)<.01f&&p.y>3&&Physics.Raycast(p,Vector3.up,out var ceiling,1.5f,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore)){float height=ceiling.distance;Box("Ceiling pipe hanger",p+Vector3.up*height*.5f,new Vector3(.025f,height,.025f),steel);}}}
  static Light RoomLight(Vector3 point,bool emergency){var go=new GameObject(emergency?"Utility room emergency light":"Utility room ceiling light");go.transform.SetParent(root);go.transform.position=point;var light=go.AddComponent<Light>();light.type=LightType.Point;light.range=8;light.intensity=emergency?2:4;light.color=emergency?new Color(.6f,.85f,1):new Color(1,.87f,.69f);light.shadows=LightShadows.Soft;Box("Light housing",point+(emergency?Vector3.left*.06f:Vector3.up*.08f),emergency?new Vector3(.18f,.22f,.3f):new Vector3(.38f,.12f,.38f),steel);if(!emergency)Box("Ceiling light bracket",point+Vector3.up*.19f,new Vector3(.025f,.24f,.025f),steel);return light;}
  static TextMesh Label(string text,Vector3 pos,Quaternion rot){var t=HotelWorldText.Create(root,text,Vector3.zero,.023f,Color.white);t.transform.SetPositionAndRotation(pos,rot*Quaternion.Euler(0,180,0));t.GetComponent<HotelWorldText>().maximumDistance=7;return t;}
  static HotelMaintenanceIncident Site(GameObject go,MaintenanceIncidentKind kind,string name,Vector3 local){var item=go.AddComponent<HotelItem>();item.kind="maintenanceIncident";item.displayName=name;var site=go.AddComponent<HotelMaintenanceIncident>();site.kind=kind;site.location=name;site.workPoint=local;var c=go.AddComponent<BoxCollider>();c.center=local;c.size=new Vector3(.65f,.8f,.45f);c.isTrigger=true;var led=GameObject.CreatePrimitive(PrimitiveType.Sphere);led.transform.SetParent(go.transform,false);led.transform.localPosition=local+Vector3.up*.35f;led.transform.localScale=Vector3.one*.06f;led.GetComponent<Renderer>().sharedMaterial=blue;UnityEngine.Object.DestroyImmediate(led.GetComponent<Collider>());site.indicator=led.GetComponent<Renderer>();var housing=Box("Status indicator housing",go.transform.TransformPoint(local+Vector3.up*.35f)+(kind==MaintenanceIncidentKind.WaterOutage?Vector3.left*.25f:Vector3.left*.15f),kind==MaintenanceIncidentKind.WaterOutage?new Vector3(.48f,.12f,.12f):new Vector3(.3f,.12f,.12f),black);housing.transform.SetParent(go.transform,true);return site;}
  static Transform Rotor(Vector3 point){var go=Box("Visible motor fan",point,new Vector3(.32f,.035f,.03f),black);Box("Motor fan cross",point,new Vector3(.035f,.32f,.03f),black).transform.SetParent(go.transform,true);return go.transform;}
  static Transform PressureGauge(Vector3 point){var face=GameObject.CreatePrimitive(PrimitiveType.Cylinder);face.name="Water pressure gauge";face.transform.SetParent(root);face.transform.SetPositionAndRotation(point,Quaternion.Euler(0,0,-90));face.transform.localScale=new Vector3(.22f,.012f,.22f);face.GetComponent<Renderer>().sharedMaterial=Mat("Gauge ivory",new Color(.9f,.88f,.77f));UnityEngine.Object.DestroyImmediate(face.GetComponent<Collider>());var pivot=new GameObject("Pressure needle pivot").transform;pivot.SetParent(root);pivot.SetPositionAndRotation(point+Vector3.right*.015f,Quaternion.Euler(0,90,0));var needle=Box("Pressure needle",pivot.position+Vector3.up*.035f,new Vector3(.012f,.085f,.012f),black);needle.transform.SetParent(pivot,true);Box("Gauge wall bracket",point-Vector3.right*.12f,new Vector3(.25f,.08f,.08f),steel);return pivot;}
  static void FuseDoor(GameObject fuse,HotelMaintenanceIncident site){var old=fuse.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.StartsWith("Lid_"));old.gameObject.SetActive(false);var center=fuse.transform.position+new Vector3(.13f,-.12f,-.05f);var lid=Model("old_fuse_box","Lid_",center,new Vector3(.49f,.44f,.035f),Quaternion.Euler(0,90,0),"Hinged electrical safety cover");var hinge=new GameObject("Fuse cover hinge").transform;hinge.SetParent(fuse.transform,false);hinge.position=center+Vector3.forward*.245f;lid.transform.SetParent(hinge,true);site.cover=hinge;}
  static void PumpMotor(Vector3 center){var motor=GameObject.CreatePrimitive(PrimitiveType.Cylinder);motor.name="Pump electric motor";motor.transform.SetParent(root);motor.transform.SetPositionAndRotation(center,Quaternion.Euler(90,0,0));motor.transform.localScale=new Vector3(.7f,.60f,.7f);motor.GetComponent<Renderer>().sharedMaterial=blue;var obstacle=motor.AddComponent<NavMeshObstacle>();obstacle.carving=true;obstacle.shape=NavMeshObstacleShape.Capsule;obstacle.radius=.5f;obstacle.height=2;for(int i=0;i<8;i++){var fin=GameObject.CreatePrimitive(PrimitiveType.Cylinder);fin.name="Motor cooling fin";fin.transform.SetParent(root);fin.transform.SetPositionAndRotation(center+Vector3.forward*(i*.11f-.4f),Quaternion.Euler(90,0,0));fin.transform.localScale=new Vector3(.76f,.014f,.76f);fin.GetComponent<Renderer>().sharedMaterial=steel;UnityEngine.Object.DestroyImmediate(fin.GetComponent<Collider>());}}
  public static object Build(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");models=pipes=0;var prior=GameObject.Find("Hotel utility infrastructure");if(prior)UnityEngine.Object.DestroyImmediate(prior);root=new GameObject("Hotel utility infrastructure").transform;steel=Mat("Utility galvanized steel",new Color(.38f,.43f,.46f));blue=Mat("Pump enamel blue",new Color(.035f,.22f,.32f));black=Mat("Utility rubber",new Color(.035f,.045f,.05f));var plant=root.gameObject.AddComponent<HotelUtilityPlant>();
