   var fuse=Model("old_fuse_box",null,new Vector3(-22.84f,1.55f,-24.7f),new Vector3(.65f,1.8f,.28f),Quaternion.Euler(0,90,0),"Main electrical distribution panel");plant.electrical=Site(fuse,MaintenanceIncidentKind.PowerOutage,"G05 ELECTRICAL ROOM / main fuse",new Vector3(0,0,.26f));plant.electrical.breaker=Box("Main breaker lever",fuse.transform.TransformPoint(new Vector3(0,-.15f,.25f)),new Vector3(.08f,.17f,.08f),blue).transform;plant.electrical.breaker.SetParent(fuse.transform,true);FuseDoor(fuse,plant.electrical);
   Model("pipe_shelf",null,new Vector3(-18.10f,1.2f,-26.8f),new Vector3(.16f,1.8f,.65f),Quaternion.identity,"Electrical conduit manifold");Model("bunch_of_electric_wires",null,new Vector3(-22.90f,2.82f,-27.2f),new Vector3(.12f,.5f,3.4f),Quaternion.identity,"Bundled generator wiring");
   for(int i=0;i<3;i++){var panel=Model("freebie_-_game_art_vintage_fuse_box",null,new Vector3(-18.19f,1.6f,-23.2f-i*.95f),new Vector3(.6f,.65f,.16f),Quaternion.Euler(0,-90,0),"Branch fuse panel",false,Quaternion.Euler(0,-90,0));Pipe(new Vector3(-18.2f,1.92f,-23.2f-i*.95f),new Vector3(-18.2f,3.2f,-23.2f-i*.95f),.045f);}
   // Pump assembled from imported industrial fittings plus a pressure vessel and motor base.
