   var pump=Model("factory_pipe_kit","pipe_valve",new Vector3(-27.66f,1.3f,-24.5f),new Vector3(.38f,.35f,.38f),Quaternion.identity,"Main water supply valve");plant.pump=Site(pump,MaintenanceIncidentKind.WaterOutage,"G06 PUMP ROOM / pressure loss",new Vector3(.28f,0,0));var handwheel=Model("factory_pipe_kit","pipe_handle",new Vector3(-27.37f,1.3f,-24.5f),new Vector3(.25f,.25f,.06f),Quaternion.Euler(0,90,0),"Pump valve handwheel").transform;var pivot=new GameObject("Handwheel animation pivot").transform;pivot.SetParent(pump.transform);pivot.position=handwheel.position;handwheel.SetParent(pivot,true);plant.pump.valve=pivot;
   for(int i=0;i<2;i++){var tank=GameObject.CreatePrimitive(PrimitiveType.Cylinder);tank.name="Pressure accumulator";tank.transform.SetParent(root);tank.transform.position=new Vector3(-24f,.94f,-26-i*1.3f);tank.transform.localScale=new Vector3(.65f,.9f,.65f);tank.GetComponent<Renderer>().sharedMaterial=blue;Box("Pressure vessel floor foot",new Vector3(-24,.04f,-26-i*1.3f),new Vector3(.72f,.08f,.72f),steel);Pipe(new Vector3(-24,1.7f,-26-i*1.3f),new Vector3(-27.75f,1.7f,-26-i*1.3f),.12f);}Pipe(new Vector3(-27.75f,1.2f,-29.5f),new Vector3(-27.75f,1.2f,-23f),.16f);Pipe(new Vector3(-27.75f,1.2f,-23),new Vector3(-27.75f,3.45f,-23),.16f);Pipe(new Vector3(-27.75f,3.45f,-23),new Vector3(-24f,3.45f,-23),.16f);
