   plant.powerStatus=Label("POWER ONLINE",new Vector3(-21.62f,2.48f,-25.7f),Quaternion.Euler(0,90,0));plant.powerStatus.characterSize=.013f;
   plant.waterStatus=Label("PRESSURE NORMAL",new Vector3(-26.35f,2.02f,-25.5f),Quaternion.Euler(0,90,0));plant.waterStatus.characterSize=.013f;
