   Pipe(new Vector3(13.18f,7.85f,-.82f),new Vector3(28,7.85f,-.82f),.045f);
   EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);return new{models,pipes,electrical=plant.electrical.Target.ToString(),water=plant.pump.Target.ToString()};
